// Worked example from a skill generated by spec2skill: one chain of calls where each output feeds
// the next input. `node run.mjs` (dry run, the default) writes plan.json next to this file and
// calls nothing; `--live` makes the calls. Options: `--set name=value` (an argument the chain does
// not fill), `--yes` (allow a destructive step). Plain ESM for Node.js 20+, no dependencies.
import { writeFileSync } from 'node:fs';
import { api, exampleArgs, operation } from '../../kit/args.mjs';

const CHAIN = /* @chain */ {"ops":["listProjects","listTasks","getTask"],"via":["id -> projectId, ownerId -> assigneeId","id -> taskId"]};
const argv = process.argv.slice(2);
const live = argv.includes('--live') && !argv.includes('--dry-run');
// Preset values (CHAIN.set), then `--set name=value` from the command line.
const set = { ...CHAIN.set, ...Object.fromEntries(argv.flatMap((a, i) => (argv[i - 1] === '--set' ? [a.split(/=(.*)/s, 2)] : []))) };
const kit = await import(api.kind === 'mcp' ? '../../kit/mcp.mjs' : '../../kit/client.mjs');
const endpoint = process.env[`${api.envPrefix}_URL`];
// Dry runs show where credentials go, never their values.
const redacted = { ...process.env, ...Object.fromEntries(api.auth.flatMap((s) => s.env.map((name) => [name, 'REDACTED']))) };

/** `id -> projectId, listed path` -> `[{ from: 'id', to: 'projectId' }, { to: 'path' }]`. */
const pairs = (via = '') => via.split(', ').flatMap((part) => {
  const m = /^(?:(\S+) -> |listed )(\S+)$/.exec(part);
  return m ? [{ from: m[1], to: m[2] }] : [];
});

/** The first value of `field` in a response (searching items and wrappers), or the first listed entry of an MCP text result. */
function pick(value, field) {
  if (field && value && typeof value === 'object') {
    if (!Array.isArray(value) && value[field] !== undefined && typeof value[field] !== 'object') return value[field];
    for (const inner of Array.isArray(value) ? value : Object.values(value)) {
      const found = pick(inner, field);
      if (found !== undefined) return found;
    }
    return undefined;
  }
  const text = value?.structuredContent ?? value?.content?.find((c) => c.type === 'text')?.text;
  if (typeof text !== 'string') return text && pick(text, field);
  return text.split('\n').map((l) => l.replace(/^\[(FILE|DIR)\]\s*/, '').trim()).find((l) => l && !l.endsWith(':'));
}

const steps = [];
let previous;
for (const [i, id] of CHAIN.ops.entries()) {
  const op = operation(id);
  const required = op.inputs.filter((p) => p.required).map((p) => p.name);
  // Earlier outputs fill required inputs only; optional filters stay unset unless `--set`.
  const fed = i ? pairs(CHAIN.via[i - 1]).filter((p) => required.includes(p.to)) : [];
  const given = Object.entries({ ...exampleArgs(id), ...set }).filter(([k]) => required.includes(k) || Object.hasOwn(set, k));
  const args = Object.fromEntries(given.filter(([k]) => op.inputs.some((p) => p.name === k)));
  for (const p of fed) {
    if (!live) continue;
    args[p.to] = pick(previous, p.from);
    if (args[p.to] === undefined) throw new Error(`${id}: ${CHAIN.ops[i - 1]} returned no ${p.from ?? 'entry'} for ${p.to}`);
  }
  const call = api.kind === 'mcp' ? kit.buildCall(id, args, i + 1) : kit.buildRequest(id, args, { env: redacted });
  if (call.headers?.authorization?.startsWith('Basic ')) call.headers.authorization = 'Basic REDACTED';
  steps.push({ step: i + 1, op: id, destructive: op.destructive, args, ...(api.kind === 'mcp' ? { endpoint: endpoint ?? `$${api.envPrefix}_URL`, call } : { request: { ...call, body: typeof call.body === 'string' ? call.body : undefined } }),
    fedBy: fed.map((p) => ({ arg: p.to, from: CHAIN.ops[i - 1], field: p.from ?? 'a listed entry' })) });
  console.log(`${i + 1}. ${id}${fed.length ? ` <- ${fed.map((p) => `${p.to} from ${CHAIN.ops[i - 1]}`).join(', ')}` : ''}`);
  if (live) {
    const options = { confirmed: argv.includes('--yes') };
    previous = api.kind === 'mcp' ? await kit.callTool(endpoint, id, args, options) : await kit.request(id, args, options);
  }
}
const plan = { skill: api.skill, mode: live ? 'live' : 'dry-run', chain: CHAIN.ops, steps };
writeFileSync(new URL('./plan.json', import.meta.url), `${JSON.stringify(plan, null, 2)}\n`);
console.log(`${live ? 'ran' : 'planned'} ${steps.length} calls; wrote plan.json`);
